// Re-generates src/assets/modelViewerSource.ts so the 3D preview works offline (no CDN).
//   npm pack @google/model-viewer@4.3.1 && tar xzf google-model-viewer-4.3.1.tgz && node scripts/bundle-viewer.mjs package/dist/model-viewer.min.js
import fs from 'node:fs';
const src = fs.readFileSync(process.argv[2], 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '').replaceAll('</script', '<\\/script');
fs.writeFileSync('src/assets/modelViewerSource.ts', `// Generated by scripts/bundle-viewer.mjs (@google/model-viewer 4.3.1, Apache-2.0). Do not edit.\nexport const MODEL_VIEWER_JS: string = ${JSON.stringify(src)};\n`);
